import 'dart:convert';

/// The do-not-edit banner, naming the command that regenerates the file.
String codegenHeader(String command) =>
    '// AUTO-GENERATED by `dart run vaultbase:types`. Do not edit.\n'
    '// Regenerate via:  $command\n';

/// The collections of a schema snapshot (`GET
/// /api/v1/admin/migrations/snapshot`): a `[...]` list, `{collections:
/// [...]}`, or either inside the `{data: ...}` envelope.
List<Map<String, dynamic>> snapshotCollections(Object? json) {
  if (json is List) {
    return [for (final c in json) (c as Map).cast<String, dynamic>()];
  }
  if (json is Map && json['collections'] is List) {
    return snapshotCollections(json['collections']);
  }
  if (json is Map && json.containsKey('data')) {
    return snapshotCollections(json['data']);
  }
  throw const FormatException('Unrecognized schema shape');
}

/// Dart source for the collections of a schema snapshot: per collection a
/// `XRecord extends RecordModel` with a getter per field, an `XCreate` (base
/// and auth collections) with `toJson()`, and `vb.collections.<name>`.
String generateDart(List<Map<String, dynamic>> collections,
    {String header = '// AUTO-GENERATED by `dart run vaultbase:types`. '
        'Do not edit.\n'}) {
  final classes = <String>[];
  final accessors = <String>[];
  final accessorNames = {
    'vb',
    'hashCode',
    'runtimeType',
    'toString',
    'noSuchMethod'
  };
  final classNames = {'Vaultbase'};
  var usesGeo = false;
  var usesGroupDate = false;
  // Group classes are named after their collection and field; kept clear of
  // every record and create class, and of the library's own.
  final typeNames = {
    'Vaultbase', 'VaultbaseCollections', 'RecordModel', 'Collection', //
    'Singleton',
  };
  final bases = <Map<String, dynamic>, String>{};
  for (final col in collections) {
    final name = col['name'];
    if (name is! String || !_collectionName.hasMatch(name)) continue;
    final base = _unique(_pascal(name), classNames);
    bases[col] = base;
    typeNames.addAll(['${base}Record', '${base}Create']);
  }

  for (final col in collections) {
    final base = bases[col];
    if (base == null) continue;
    final name = col['name'] as String;
    final type = col['type'] as String? ?? 'base';
    final fields = [
      for (final f in _parseFields(col['fields']))
        if (_keepField(f, type)) f
    ];
    for (final f in fields.where((f) => f.type == 'group')) {
      final cls = _unique(
          '$base${_pascal(f.name)}${f.groupList ? 'Item' : ''}', typeNames);
      f.groupClass = cls;
      classes.add(_emitGroup(cls, name, f));
      usesGroupDate = usesGroupDate || f.subfields.any((s) => s.type == 'date');
    }
    final names = _fieldNames(
        fields, type == 'auth' ? _recordMembers : _recordMembersNoAuth);
    usesGeo = usesGeo || fields.any((f) => f.type == 'geoPoint');

    final accessor = _unique(_safeIdent(_camel(name)), accessorNames);
    classes.add(_emitRecord('${base}Record', name, type, fields, names));
    if (type == 'base' || type == 'auth') {
      classes.add(_emitCreate(
          '${base}Create',
          name,
          type,
          [
            for (final f in fields)
              if (f.type != 'autodate') f
          ],
          names,
          accessor));
    }

    final quoted = _dartString(name);
    accessors.add(type == 'singleton'
        ? '  Singleton<${base}Record> get $accessor =>\n'
            '      vb.singletonOf($quoted, ${base}Record.fromJson);'
        : '  Collection<${base}Record> get $accessor =>\n'
            '      vb.collectionOf($quoted, ${base}Record.fromJson);');
  }

  final parts = [
    header.trimRight(),
    '// ignore_for_file: type=lint',
    '',
    "import 'package:vaultbase/vaultbase.dart';",
    '',
    classes.join('\n\n'),
    '',
    '/// Each collection with its record type: `vb.collections.posts.list()`.',
    'class VaultbaseCollections {',
    '  const VaultbaseCollections(this.vb);',
    '',
    '  final Vaultbase vb;',
    if (accessors.isNotEmpty) ...['', accessors.join('\n\n')],
    '}',
    '',
    'extension VaultbaseSchema on Vaultbase {',
    '  VaultbaseCollections get collections => VaultbaseCollections(this);',
    '}',
    if (usesGeo) ...[
      '',
      '({double lat, double lng})? _geoPoint(Object? v) => v is Map &&',
      "        v['lat'] is num &&",
      "        v['lng'] is num",
      "    ? (lat: (v['lat'] as num).toDouble(), "
          "lng: (v['lng'] as num).toDouble())",
      '    : null;',
    ],
    if (usesGroupDate) ...[
      '',
      'DateTime? _groupDate(Object? v) => v is num',
      '    ? DateTime.fromMillisecondsSinceEpoch(v.toInt() * 1000, isUtc: true)',
      '    : null;',
    ],
    '',
  ];
  return parts.join('\n');
}

final _collectionName = RegExp(r'^[A-Za-z_][A-Za-z0-9_]{0,62}$');
final _fieldName = RegExp(r'^[A-Za-z_][A-Za-z0-9_]*$');

const _keywords = {
  'abstract', 'as', 'assert', 'async', 'await', 'base', 'break', 'case', //
  'catch', 'class', 'const', 'continue', 'covariant', 'default', 'deferred',
  'do', 'dynamic', 'else', 'enum', 'export', 'extends', 'extension',
  'external', 'factory', 'false', 'final', 'finally', 'for', 'Function',
  'get', 'hide', 'if', 'implements', 'import', 'in', 'interface', 'is',
  'late', 'library', 'mixin', 'new', 'null', 'of', 'on', 'operator', 'part',
  'required', 'rethrow', 'return', 'sealed', 'set', 'show', 'static',
  'super', 'switch', 'sync', 'this', 'throw', 'true', 'try', 'type',
  'typedef', 'var', 'void', 'when', 'while', 'with', 'yield',
};

/// Members of RecordModel and Object a field getter must not shadow.
const _recordMembersNoAuth = {
  'id', 'created', 'updated', 'createdAt', 'updatedAt', 'data', //
  'getString', 'getInt', 'getDouble', 'getBool', 'getList', 'getDate',
  'expandOne', 'expandMany', 'toJson', 'toString', 'hashCode',
  'runtimeType', 'noSuchMethod',
};

/// Plus the getters emitted for every auth collection.
const _recordMembers = {
  ..._recordMembersNoAuth,
  'email', 'emailVerified', 'totpEnabled', 'isAnonymous', //
};

class _Field {
  _Field(Map<String, dynamic> json)
      : name = json['name'] as String? ?? '',
        type = json['type'] as String? ?? '',
        required = json['required'] == true,
        system = json['system'] == true,
        multiple = (json['options'] as Map?)?['multiple'] == true,
        groupList = (json['options'] as Map?)?['multiple'] != false,
        subfields = _parseFields((json['options'] as Map?)?['fields']);

  final String name;
  final String type;
  final bool required;
  final bool system;
  final bool multiple;

  /// A group: a list of items (the default), or one object.
  final bool groupList;

  /// A group's subfields.
  final List<_Field> subfields;

  /// The class generated for a group's items.
  String? groupClass;

  bool get isList =>
      type == 'vector' || ((type == 'select' || type == 'file') && multiple);
}

List<_Field> _parseFields(Object? raw) {
  Object? list = raw;
  if (raw is String) {
    try {
      list = jsonDecode(raw);
    } on FormatException {
      return const [];
    }
  }
  if (list is! List) return const [];
  return [
    for (final f in list)
      if (f is Map) _Field(f.cast<String, dynamic>())
  ];
}

bool _keepField(_Field f, String collectionType) {
  if (f.system || f.type == 'password') return false;
  if (!_fieldName.hasMatch(f.name)) return false;
  if (const {'id', 'created', 'updated'}.contains(f.name)) return false;
  // Emitted for every auth collection; snapshots also list them as implicit
  // fields.
  if (collectionType == 'auth' &&
      const {'email', 'password', 'verified', 'email_verified'}
          .contains(f.name)) {
    return false;
  }
  return true;
}

/// Dart names for the fields, shared by the record and create classes.
Map<String, String> _fieldNames(List<_Field> fields, Set<String> reserved) {
  final taken = <String>{};
  return {
    for (final f in fields)
      f.name: _unique(() {
        final n = _safeIdent(_camel(f.name));
        return reserved.contains(n) ? '${n}Field' : n;
      }(), taken),
  };
}

String _emitRecord(String className, String collection, String type,
    List<_Field> fields, Map<String, String> names) {
  final lines = [
    '/// A record of `$collection`.',
    'class $className extends RecordModel {',
    '  $className(super.data);',
    '',
    '  factory $className.fromJson(Map<String, dynamic> json) => '
        '$className(json);',
  ];
  if (type == 'auth') {
    lines.addAll([
      '',
      "  String get email => getString('email');",
      '',
      "  bool get emailVerified => getBool('email_verified');",
      '',
      "  bool get totpEnabled => getBool('totp_enabled');",
      '',
      "  bool get isAnonymous => getBool('is_anonymous');",
    ]);
  }
  for (final f in fields) {
    // A singleton's record starts with every field empty, required or not.
    final required = f.required && type != 'singleton';
    lines.addAll([
      '',
      '  ${_readType(f, required)} get ${names[f.name]} => '
          '${_readExpr(f, required)};',
    ]);
  }
  lines.add('}');
  return lines.join('\n');
}

String _emitCreate(String className, String collection, String type,
    List<_Field> fields, Map<String, String> names, String accessor) {
  final params = <String>[];
  final members = <String>[];
  final json = <String>[];
  if (type == 'auth') {
    params.addAll(['required this.email', 'required this.password']);
    members.addAll(['final String email;', 'final String password;']);
    json.addAll(["'email': email", "'password': password"]);
  }
  for (final f in fields) {
    final n = names[f.name]!;
    final key = _dartString(f.name);
    final t = _writeType(f);
    params.add(f.required ? 'required this.$n' : 'this.$n');
    members.add('final ${f.required ? t : '$t?'} $n;');
    final v = _writeExpr(f, f.required ? n : '$n!');
    json.add(f.required ? '$key: $v' : 'if ($n != null) $key: $v');
  }
  // Auth records are made by signing up, never by a plain create.
  final usage = type == 'auth'
      ? [
          '/// Fields for a new `$collection` account:',
          '/// `auth.collection(${_dartString(collection)})'
              '.register(u.email, u.password, data: u.toJson())`.',
        ]
      : [
          '/// Fields for a new `$collection` record:',
          '/// `collections.$accessor.create($className(...).toJson())`.',
        ];
  return [
    ...usage,
    'class $className {',
    params.isEmpty
        ? '  const $className();'
        : '  const $className({${params.join(', ')}});',
    for (final m in members) ...['', '  $m'],
    '',
    '  Map<String, dynamic> toJson() => {${json.join(', ')}};',
    '}',
  ].join('\n');
}

/// Members a subfield's Dart name must not take.
const _groupMembers = {
  'id', 'fromJson', 'toJson', 'toString', 'hashCode', 'runtimeType', //
  'noSuchMethod',
};

/// The class for a group's items (or its one object): a final member per
/// subfield, `fromJson` and `toJson`. A list item keeps the `id` the server
/// gave it, so sending it back updates that item.
String _emitGroup(String className, String collection, _Field group) {
  final subs = [
    for (final s in group.subfields)
      if (_fieldName.hasMatch(s.name)) s
  ];
  final names = _fieldNames(subs, _groupMembers);
  final params = <String>[if (group.groupList) 'this.id'];
  final members = <String>[
    if (group.groupList)
      '/// Set by the server; keep it when sending the item back.\n'
          'final String? id;',
  ];
  final reads = <String>[if (group.groupList) "id: json['id'] as String?"];
  final writes = <String>[if (group.groupList) "if (id != null) 'id': id"];
  for (final s in subs) {
    final n = names[s.name]!;
    final key = _dartString(s.name);
    final t = _subType(s);
    final nullable = t.endsWith('?') || !s.required;
    params.add(s.required ? 'required this.$n' : 'this.$n');
    members.add('final ${nullable && !t.endsWith('?') ? '$t?' : t} $n;');
    reads.add('$n: ${_subRead(s, "json[$key]")}');
    final v = _subWrite(s, nullable ? '$n!' : n);
    writes.add(nullable ? 'if ($n != null) $key: $v' : '$key: $v');
  }
  final what = group.groupList ? 'An item of' : 'The value of';
  return [
    '/// $what `$collection.${group.name}`.',
    'class $className {',
    '  const $className({${params.join(', ')}});',
    '',
    '  factory $className.fromJson(Map<String, dynamic> json) => $className(',
    for (final r in reads) '        $r,',
    '      );',
    for (final m in members) ...['', for (final l in m.split('\n')) '  $l'],
    '',
    '  Map<String, dynamic> toJson() => {${writes.join(', ')}};',
    '}',
  ].join('\n');
}

String _subType(_Field s) {
  if (s.type == 'select' && s.multiple) return 'List<String>';
  return switch (s.type) {
    'date' => 'DateTime',
    'json' => 'Object?',
    _ => _scalar(s),
  };
}

/// A subfield read from an item. A required one that an older item lacks
/// reads as the type's empty value, as a required record field does.
String _subRead(_Field s, String v) {
  if (s.type == 'select' && s.multiple) {
    final list = '[for (final e in $v as List) if (e is String) e]';
    return s.required
        ? '$v is List ? $list : const <String>[]'
        : '$v is List ? $list : null';
  }
  switch (s.type) {
    case 'date':
      return s.required
          ? '_groupDate($v) ?? DateTime.fromMillisecondsSinceEpoch(0, isUtc: true)'
          : '_groupDate($v)';
    case 'json':
      return v;
  }
  final t = _scalar(s);
  if (t == 'Object') return v;
  if (!s.required) return '$v as $t?';
  return switch (t) {
    'String' => "$v as String? ?? ''",
    'bool' => '$v as bool? ?? false',
    _ => '$v as num? ?? 0',
  };
}

String _subWrite(_Field s, String v) =>
    s.type == 'date' ? '$v.toUtc().toIso8601String()' : v;

String _scalar(_Field f) => switch (f.type) {
      'number' => 'num',
      'bool' => 'bool',
      'text' ||
      'email' ||
      'url' ||
      'editor' ||
      'relation' ||
      'color' ||
      'select' ||
      'file' ||
      'password' =>
        'String',
      _ => 'Object',
    };

String _readType(_Field f, bool required) {
  if (f.type == 'group') {
    return f.groupList ? 'List<${f.groupClass}>' : '${f.groupClass}?';
  }
  if (f.isList) return f.type == 'vector' ? 'List<double>' : 'List<String>';
  switch (f.type) {
    case 'date' || 'autodate':
      return 'DateTime?';
    case 'json':
      return 'Object?';
    case 'geoPoint':
      return '({double lat, double lng})?';
  }
  final t = _scalar(f);
  return required && t != 'Object' ? t : '$t?';
}

String _readExpr(_Field f, bool required) {
  final key = _dartString(f.name);
  if (f.type == 'group') {
    return f.groupList
        ? '[for (final v in getList<Map<dynamic, dynamic>>($key)) '
            '${f.groupClass}.fromJson(v.cast<String, dynamic>())]'
        : 'data[$key] is Map ? ${f.groupClass}.fromJson('
            '(data[$key] as Map).cast<String, dynamic>()) : null';
  }
  if (f.isList) {
    return f.type == 'vector'
        ? '[for (final v in getList<num>($key)) v.toDouble()]'
        : 'getList<String>($key)';
  }
  switch (f.type) {
    case 'date' || 'autodate':
      return 'getDate($key)';
    case 'json':
      return 'data[$key]';
    case 'geoPoint':
      return '_geoPoint(data[$key])';
  }
  final t = _scalar(f);
  if (t == 'Object') return 'data[$key]';
  if (required) {
    return switch (t) {
      'String' => 'getString($key)',
      'bool' => 'getBool($key)',
      _ => 'data[$key] as num? ?? 0',
    };
  }
  if (t == 'bool') return 'data[$key] == null ? null : getBool($key)';
  return 'data[$key] as $t?';
}

String _writeType(_Field f) {
  if (f.type == 'group') {
    return f.groupList ? 'List<${f.groupClass}>' : f.groupClass!;
  }
  if (f.isList) return f.type == 'vector' ? 'List<double>' : 'List<String>';
  return switch (f.type) {
    'date' => 'DateTime',
    'json' => 'Object',
    'geoPoint' => '({double lat, double lng})',
    _ => _scalar(f),
  };
}

String _writeExpr(_Field f, String v) => switch (f.type) {
      'group' when f.groupList => '[for (final i in $v) i.toJson()]',
      'group' => '$v.toJson()',
      'date' => '$v.toUtc().toIso8601String()',
      'geoPoint' => "{'lat': $v.lat, 'lng': $v.lng}",
      _ => v,
    };

String _camel(String s) {
  final parts = s.split(RegExp('[^A-Za-z0-9]+')).where((p) => p.isNotEmpty);
  if (parts.isEmpty) return 'field';
  final first = parts.first;
  return first[0].toLowerCase() +
      first.substring(1) +
      parts.skip(1).map((p) => p[0].toUpperCase() + p.substring(1)).join();
}

String _pascal(String s) {
  final c = _camel(s);
  return c[0].toUpperCase() + c.substring(1);
}

/// A Dart identifier: not a keyword, not starting with a digit.
String _safeIdent(String s) {
  var n = RegExp('^[0-9]').hasMatch(s) ? 'f$s' : s;
  if (_keywords.contains(n)) n = '${n}Field';
  return n;
}

String _unique(String n, Set<String> taken) {
  var out = n;
  for (var i = 2; taken.contains(out); i++) {
    out = '$n$i';
  }
  taken.add(out);
  return out;
}

String _dartString(String s) =>
    "'${s.replaceAll(r'\', r'\\').replaceAll("'", r"\'").replaceAll(r'$', r'\$')}'";
